<template><div class="password-reset-page"><Teleport defer to="#page-header-actions"><RouterLink class="nav-btn" to="/?login=true">返回登录</RouterLink></Teleport><main class="reset-card"><h1>找回密码</h1><p>使用注册邮箱验证身份。</p><form @submit.prevent="reset"><label>注册邮箱<input v-model="email" type="email" autocomplete="email" maxlength="254" required /></label><div class="code-row"><label>邮箱验证码<input v-model="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required /></label><button type="button" :disabled="sending || seconds>0 || busy" @click="send">{{ seconds>0?`${seconds} 秒后重试`:'发送验证码' }}</button></div><label>新密码<input v-model="password" type="password" autocomplete="new-password" minlength="8" required /></label><label>再次输入新密码<input v-model="repeat" type="password" autocomplete="new-password" required /></label><small>至少8个字符，不超过72字节。验证码10分钟内有效，最多尝试5次。</small><button :disabled="busy || sending">{{ busy?'正在更新…':'更新密码' }}</button></form><p role="status">{{ message }}</p><RouterLink v-if="done" to="/?login=true">密码已更新，前往登录 ↗</RouterLink></main></div></template>
<script setup lang="ts">
import {ref,onUnmounted} from 'vue';import request from '@/utils/request';import {signOutSession} from '@/utils/authSession'
const email=ref(''),code=ref(''),password=ref(''),repeat=ref(''),busy=ref(false),sending=ref(false),seconds=ref(0),message=ref(''),done=ref(false);let timer:ReturnType<typeof setInterval>|undefined
async function send(){if(sending.value || seconds.value>0)return;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)){message.value='请输入有效的注册邮箱';return}sending.value=true;try{const r:any=await request.post('/auth/password/code',{email:email.value});message.value=r.message;seconds.value=60;clearInterval(timer);timer=setInterval(()=>{if(--seconds.value<=0)clearInterval(timer)},1000)}catch(e){message.value=e instanceof Error?e.message:'发送失败'}finally{sending.value=false}}
async function reset(){if(busy.value)return;if(password.value!==repeat.value){message.value='两次新密码不一致';return}if(new TextEncoder().encode(password.value).length>72){message.value='密码不能超过72字节';return}busy.value=true;try{await request.post('/auth/password/reset',{email:email.value,code:code.value,password:password.value});password.value=repeat.value=code.value='';done.value=true;message.value='密码已更新，请重新登录';if(localStorage.getItem('email')?.toLowerCase()===email.value.trim().toLowerCase())await signOutSession()}catch(e){message.value=e instanceof Error?e.message:'更新失败'}finally{busy.value=false}}
onUnmounted(()=>clearInterval(timer))
</script>
<style scoped>.navbar{height:76px;padding:0 4%;display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:1px solid var(--ej-line);background:var(--ej-canvas)}.logo{color:var(--ej-ink);font-size:24px;font-weight:850;text-decoration:none;display:inline-flex;align-items:center;gap:10px}.navbar>a{color:var(--ej-ink);text-decoration:none}.reset-card{max-width:480px;margin:64px auto;padding:32px;border:1px solid var(--ej-line);border-radius:24px;background:var(--ej-surface)}h1{font-size:28px}p,small{color:var(--ej-muted)}form,label{display:grid;gap:10px}form{gap:18px}input{min-width:0;width:100%;box-sizing:border-box;padding:12px;border:1px solid var(--ej-line);border-radius:12px;background:var(--ej-bg)}button{border:1px solid var(--ej-line);border-radius:99px;padding:10px 16px;background:var(--studio-lime);cursor:pointer}button:disabled{opacity:.5}.code-row{display:flex;gap:12px;align-items:end}.code-row label{flex:1;min-width:0}.code-row button{background:var(--ej-surface);white-space:nowrap}@media(max-width:600px){.reset-card{margin:30px 16px;padding:24px}}</style>
